mapper.select:
select t.similar,t.inout_id,t.inout_id inoutId,t.machine_id,t.machine_id machineId,t.machine_code,t.machine_code
machineCode,t.open_type_cd,t.open_type_cd openTypeCd,t.id_card,t.id_card
idCard,t.name,t.tel,t.status_cd,t.status_cd statusCd,t.face_path,t.face_path
facePath,t.state,t.community_id,t.community_id communityId,ac.machine_name machineName,t.create_time createTime
from access_control_inout t
left join access_control ac on t.machine_id = ac.machine_id and ac.status_cd = '0'
where 1 =1

    and t.similar= #{similar}


    and t.inout_id= #{inoutId}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.open_type_cd= #{openTypeCd}


    and t.id_card= #{idCard}


    and t.name= #{name}


    and t.tel= #{tel}


    and t.tel in

        #{item}



    and t.status_cd= #{statusCd}


    and t.face_path= #{facePath}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.create_time >= #{queryStartTime}


    and t.create_time <= #{queryEndTime}

order by t.create_time desc

    limit #{page}, #{row}

